// Start-Bibliothek „Correctives“ – erzeugt mit tools_src/make_correctives_lib.py (nicht von Hand ändern)
// Quellen: BER = Maiks Homework-Blätter, FT/FMS/LA = Warm-Up-Bibliothek, sonst Autor/System als Orientierung
const CR_SEED_V = 3;
const CR_SEED = [{"id": "cr000","name": "Crocodile Breathing","type": "Atmung","region": "Atmung","desc": "1. Bauchlage, Füße nach außen gedreht\n2. Stirn auf dem Handrücken ablegen, Schultern entspannt\n3. ausschließlich Nasenatmung in den Bauch (Ausdehnung zum Boden und zu den Seiten)\n4. Atemrhythmus: 4 Sek. ein – 6–8 Sek. aus","expl": "","dosage": "10 Atemzyklen","src": "BER"},{"id": "cr001","name": "BOLT Breathing Exercise","type": "Atmung","region": "Atmung","desc": "1. Stand, ruhig ein- und ausatmen\n2. nach ungezwungenem Ausatmen Luft anhalten (evtl. Nase zuhalten)\n3. gehen und Schritte zählen bis zum ersten „Lufthunger“, dann ruhig durch die Nase weiteratmen","expl": "","dosage": "1–2x","src": "BER"},{"id": "cr002","name": "Foam Rolling – Thoracic Spine","type": "Selbstmassage","region": "Brustwirbelsäule","desc": "1. Rückenlage bzw. sitzend vor dem Foam Roller\n2. Becken anheben und Körpergewicht auf den Foam Roller bringen\n3. Arme überkreuzen und Schultern nach vorn ziehen\n4. entlang der Brustwirbelsäule rollen","expl": "","dosage": "1–2 Min.","src": "BER"},{"id": "cr003","name": "Foam Rolling – Thoracic Extension (Segmental)","type": "Selbstmassage","region": "Brustwirbelsäule","desc": "1. sitzend vor dem Foam Roller/Duoball\n2. Hände um die Schultern, später überkopf gestreckt\n3. Gesäß anheben, Bauch angespannt\n4. über jedes Segment einzeln beugen/strecken\n5. vom Rippenbogen bis zu den Schulterblättern ausrollen","expl": "","dosage": "5 Atemzyklen pro Segment","src": "BER"},{"id": "cr004","name": "Foam Rolling – Sole of the Foot","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Stand\n2. Golf- oder Tennisball mit Druck unter der Fußsohle entlang rollen\n3. bei Hotspots Zehen beugen/strecken","expl": "","dosage": "1–2 Min. pro Seite","src": "BER"},{"id": "cr005","name": "Foam Rolling – Calf","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. sitzend\n2. Körpergewicht auf eine Wade bringen und von der Ferse bis zur Kniekehle rollen\n3. zwischendurch den Fuß nach außen/innen drehen, bei Hotspots Fuß kreisen","expl": "","dosage": "1–2 Min. pro Seite","src": "BER"},{"id": "cr006","name": "Foam Rolling – Lateral Calf","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Seitlage\n2. Außenseite der Wade entlang rollen\n3. bei Hotspots Fuß kreisen","expl": "","dosage": "2 Min. pro Seite","src": "BER"},{"id": "cr007","name": "Foam Rolling – Hamstrings (Ball, seated)","type": "Selbstmassage","region": "Hüfte","desc": "1. sitzend auf Kasten o. Ä., Beine hängen frei\n2. Faszienball mit Druck unter dem Oberschenkel von der Kniekehle bis zum Sitzbeinhöcker rollen\n3. bei Hotspots Knie beugen/strecken","expl": "","dosage": "1–2 Min. pro Seite","src": "BER"},{"id": "cr008","name": "Foam Rolling – Quadriceps","type": "Selbstmassage","region": "Hüfte","desc": "1. Unterarmstütz\n2. Körpergewicht auf einen Oberschenkel bringen und vom Knie bis zur Hüfte rollen\n3. zwischendurch das Bein nach außen/innen drehen","expl": "","dosage": "2 Min. pro Seite","src": "BER"},{"id": "cr009","name": "Knee to Wall – 3 Positions","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. stehend vor der Wand (Abstand prüfen)\n2. Kniescheibe innen / mittig / außen zur Wand drücken, Ferse bleibt unten\n(Variation: mit Heavy-Band)","expl": "","dosage": "3x7 pro Seite","src": "BER"},{"id": "cr010","name": "Ankle Tilts","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. Stand in Schrittstellung\n2. vorderen Fuß nach links und rechts kippen (Neutralstellung)\n3. dasselbe mit 45° nach außen gedrehtem Fuß\n4. dasselbe mit 45° nach innen gedrehtem Fuß","expl": "","dosage": "30 Sek. pro Richtung/Seite","src": "BER"},{"id": "cr011","name": "Ankle Circles (half-kneeling)","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. halber Kniestand\n2. Oberkörper über den vorderen Oberschenkel legen\n3. halbe Kreise über die Zehen schieben\n4. optional mit Heavy-Band (zieht nach hinten-unten)","expl": "","dosage": "5–10x pro Seite","src": "BER"},{"id": "cr012","name": "Assisted Straight Leg Stretch + Ankle Circles","type": "Mobilisation","region": "Hüfte","desc": "1. Rückenlage\n2. Bein mit Heavy-Band gestreckt passiv halten\n3. Sprunggelenk kreisen","expl": "","dosage": "2x 2 Min. pro Seite","src": "BER"},{"id": "cr013","name": "Leg Raise + Core Engagement","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rückenlage\n2. Core mit Heavy-Band aktivieren (leichter Zug überkopf)\n3. Bein gestreckt anheben und absenken, Fußspitze nach oben ziehen","expl": "","dosage": "10x pro Seite","src": "BER"},{"id": "cr014","name": "Toe Touch Progression","type": "Bewegungsmuster","region": "Hüfte","desc": "1. Stand: a) erhöhte Spitzen b) erhöhte Fersen c) flach\n2. Handtuch zwischen den Knien leicht zusammendrücken\n3. aus der Streckung (Arme überkopf) Fußspitzen berühren und aufrichten","expl": "","dosage": "10x pro Variation","src": "BER"},{"id": "cr015","name": "Bird Dog","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. Vierfüßlerstand: Hände unter den Schultern, Knie unter den Hüften\n2. rechten Arm/linkes Bein strecken\n3. Ellbogen und Knie unter dem Körper zusammenführen\n4. Schulterblätter „weg von den Ohren“ halten, Rücken neutral","expl": "","dosage": "3x8 pro Seite","src": "BER"},{"id": "cr016","name": "Easy Rolls (Segmental Rolling)","type": "Bewegungsmuster","region": "Rumpf","desc": "1. Rückenlage, Arme überkopf gestreckt, Beine lang\n2. einen Arm und Kopf heben und ausschließlich über diesen Arm in die Bauchlage drehen (Beine ganz locker) und zurück\n3. Blick folgt dem Arm\n4. dasselbe nur über ein Bein","expl": "","dosage": "7x hin/zurück pro Seite","src": "BER"},{"id": "cr017","name": "Lunge + External Rotation","type": "Mobilisation","region": "Hüfte","desc": "1. Ausfallschritt-Position\n2. Knie mit der gleichseitigen Hand federnd vom Körper weg/nach außen drücken\n3. optional mit Heavy-Band (zieht nach außen)","expl": "","dosage": "5–10x pro Seite","src": "BER"},{"id": "cr018","name": "Child's Pose + T-Spine Rotation","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Fersensitz\n2. Oberkörper auf die Oberschenkel legen, einen Arm nach vorn strecken\n3. anderen Arm auf die Lendenwirbelsäule legen und zur gleichen Seite aufdrehen","expl": "","dosage": "10 Atemzyklen pro Seite","src": "BER"},{"id": "cr019","name": "Baby Rockers","type": "Mobilisation","region": "Hüfte","desc": "1. Kniestand mit weit geöffneten Knien (Abduktion)\n2. Füße nach außen abgelegt\n3. Oberkörper aufrecht oder vorgebeugt nach hinten wippen (Becken Richtung Boden)","expl": "","dosage": "1–5 Min.","src": "BER"},{"id": "cr020","name": "Seated Hip Rotation (90/90 switch)","type": "Mobilisation","region": "Hüfte","desc": "1. sitzend, Hände hinter dem Körper\n2. Knie im rechten Winkel nach links/rechts ablegen\n(Variation: nur ein Knie nach innen rotieren)","expl": "","dosage": "2 Min.","src": "BER"},{"id": "cr021","name": "T-Spine Rotation (quadruped)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Bankstellung, eine Hand am Hinterkopf\n2. mit dem Ellbogen Richtung Boden/Gegenhand drehen, dann nach oben aufdrehen\n(Variation: Liegestützposition, ein Bein nach vorn)","expl": "","dosage": "10x pro Seite","src": "BER"},{"id": "cr022","name": "Deep Squat Progression","type": "Bewegungsmuster","region": "Hüfte","desc": "1. Stand, mit gestreckten Knien die Fußspitzen greifen\n2. in die tiefe Hocke „ziehen“\n3. abwechselnd linken/rechten Arm nach oben aufdrehen\n4. beide Arme überkopf strecken und aufstehen","expl": "","dosage": "10x","src": "BER"},{"id": "cr023","name": "Plank with Toe Taps","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. Unterarmstütz\n2. Fußspitzen im Wechsel kurz anheben, Becken bleibt ruhig","expl": "","dosage": "3x30 Sek. (+5 Sek. pro Einheit)","src": "BER"},{"id": "cr024","name": "Side Plank with Leg Lift","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. Seitstütz\n2. gestrecktes oberes Bein anheben/absenken","expl": "","dosage": "3x30 Sek. pro Seite (+5 Sek. pro Einheit)","src": "BER"},{"id": "cr025","name": "Bridge March","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rückenlage, Beine angestellt, Becken anheben\n2. auf der Stelle marschieren, Becken bleibt waagerecht","expl": "","dosage": "3x30 Sek. (+5 Sek. pro Einheit)","src": "BER"},{"id": "cr026","name": "90/90 Breathing with Reach (Hip Lift)","type": "Atmung","region": "Atmung","desc": "1. Rückenlage, Füße an der Wand, Hüfte und Knie 90°\n2. Becken leicht anheben (Ferse drückt in die Wand), Arme nach vorn strecken\n3. durch die Nase ein, lang durch den Mund aus, Rippen sinken nach unten","expl": "","dosage": "4–5 Atemzüge, 2–3 Runden","src": "PRI/Cook"},{"id": "cr027","name": "Supported Child's Pose Breathing","type": "Atmung","region": "Atmung","desc": "1. Fersensitz, Stirn auf den Händen\n2. in den unteren Rücken und die Flanken atmen\n3. Ausatmung doppelt so lang wie Einatmung","expl": "","dosage": "6–8 Atemzüge","src": "BER"},{"id": "cr028","name": "Rolling – Upper Body Driven","type": "Bewegungsmuster","region": "Rumpf","desc": "1. Rückenlage, Arme und Beine lang\n2. nur mit Kopf und einem Arm in die Bauchlage drehen, Beine passiv\n3. zurück ebenso, ohne Schwung","expl": "","dosage": "3–5x pro Seite","src": "Cook/FMS"},{"id": "cr029","name": "Rolling – Lower Body Driven","type": "Bewegungsmuster","region": "Rumpf","desc": "1. Rückenlage\n2. nur mit einem Bein (Knie über die Körpermitte) in die Bauchlage drehen, Oberkörper passiv\n3. zurück ebenso","expl": "","dosage": "3–5x pro Seite","src": "Cook/FMS"},{"id": "cr030","name": "Quadruped Rocking","type": "Bewegungsmuster","region": "Ganzkörper","desc": "1. Vierfüßlerstand, Rücken neutral, Blick nach vorn unten\n2. Gesäß Richtung Fersen und zurück schaukeln\n3. Rückenposition bleibt unverändert","expl": "","dosage": "10–20x","src": "Original Strength/Cook"},{"id": "cr031","name": "Active Straight Leg Raise – Leg Lowering (Band)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rückenlage, ein Bein senkrecht (am Türrahmen oder mit Band gehalten)\n2. anderes Bein gestreckt langsam ab- und wieder anheben\n3. Lendenwirbelsäule bleibt ruhig, Fußspitze angezogen","expl": "","dosage": "2x8–10 pro Seite","src": "Cook/FMS"},{"id": "cr032","name": "Leg Lowering – Unsupported","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rückenlage, beide Beine senkrecht\n2. ein Bein gestreckt langsam absenken, anderes bleibt oben\n3. Becken stabil, Rippen unten","expl": "","dosage": "2x6–8 pro Seite","src": "Cook/FMS"},{"id": "cr033","name": "Brettzel Stretch","type": "Dehnung","region": "Hüfte","desc": "1. Seitlage, oberes Knie 90° vor dem Körper (auf Kissen/Rolle)\n2. untere Hand hält das obere Knie am Boden, obere Hand zieht den unteren Fuß (Ferse zum Gesäß)\n3. Oberkörper in der Ausatmung nach hinten aufdrehen","expl": "","dosage": "5–6 Atemzüge pro Seite","src": "Cook/Jones"},{"id": "cr034","name": "Hip Internal Rotation – 90/90 Lift-Offs","type": "Mobilisation","region": "Hüfte","desc": "1. 90/90-Sitz, Oberkörper aufrecht\n2. hinteren Fuß/Knie kurz vom Boden lösen (Innenrotation aktiv)\n3. kontrolliert ablegen","expl": "","dosage": "2x6–8 pro Seite","src": "Mobility/FRC"},{"id": "cr035","name": "Glute Bridge","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rückenlage, Füße hüftbreit aufgestellt\n2. Bauch leicht anspannen, Becken über die Fersen hochdrücken\n3. oben 2 Sek. halten, keine Hohlkreuz-Position","expl": "","dosage": "2–3x10","src": "Boyle"},{"id": "cr036","name": "Single-Leg Glute Bridge (Cook Hip Lift)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rückenlage, ein Knie mit beiden Händen an die Brust ziehen\n2. über die Ferse des anderen Beins Becken anheben\n3. Knie bleibt an der Brust – kein Ausweichen ins Hohlkreuz","expl": "","dosage": "2x8 pro Seite","src": "Cook/Boyle"},{"id": "cr037","name": "Side-Lying Clamshell (Band)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Seitlage, Knie 45° gebeugt, Band über den Knien\n2. oberes Knie öffnen, Fersen bleiben zusammen\n3. Becken nicht nach hinten kippen","expl": "","dosage": "2x12–15 pro Seite","src": "Boyle"},{"id": "cr038","name": "Lateral Band Walk (Mini Band)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Mini-Band über den Knien oder Füßen, leichte Hocke\n2. kleine Seitschritte, Knie über den Zehen\n3. Oberkörper ruhig","expl": "","dosage": "2x10 Schritte pro Richtung","src": "Boyle"},{"id": "cr039","name": "Supine Psoas March (Mini Band)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rückenlage, Mini-Band um die Füße, Hüfte/Knie 90°\n2. ein Bein strecken, das andere aktiv zur Brust ziehen\n3. Lendenwirbelsäule bleibt am Boden","expl": "","dosage": "2x8 pro Seite","src": "Boyle/Cressey"},{"id": "cr040","name": "Standing Hip Flexion Iso (Wall)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Rücken zur Wand, ein Knie über 90° hochziehen\n2. Knie aktiv oben halten, ohne Hände\n3. aufrechter Oberkörper","expl": "","dosage": "3x10 Sek. pro Seite","src": "Cressey"},{"id": "cr041","name": "Hip Airplane (assisted)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Einbeinstand mit Halt, Oberkörper nach vorn geneigt (Hüftbeuge)\n2. Becken langsam auf- und zudrehen\n3. Standbein-Knie stabil über dem Fuß","expl": "","dosage": "2x5 pro Seite","src": "McGill"},{"id": "cr042","name": "Copenhagen Adductor (short lever)","type": "Stabilität/Aktivierung","region": "Hüfte","desc": "1. Seitstütz, oberes Knie auf einer Bank, unteres Bein frei\n2. Becken anheben und halten\n3. Körper in einer Linie","expl": "","dosage": "2–3x15–20 Sek. pro Seite","src": "Copenhagen-Protokoll"},{"id": "cr043","name": "McGill Curl-Up","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. Rückenlage, ein Bein gestreckt, ein Knie gebeugt, Hände unter der LWS\n2. Kopf und Schultern minimal abheben, Nacken lang\n3. 8–10 Sek. halten, ruhig weiteratmen","expl": "","dosage": "3–5 Wdh. à 10 Sek. (abfallende Pyramide)","src": "McGill"},{"id": "cr044","name": "Side Plank (knees or feet)","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. Seitstütz auf dem Unterarm, Ellbogen unter der Schulter\n2. Becken anheben, Körper in einer Linie\n3. ruhig atmen","expl": "","dosage": "3–5x10 Sek. pro Seite","src": "McGill"},{"id": "cr045","name": "Dead Bug","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. Rückenlage, Arme senkrecht, Hüfte/Knie 90°\n2. gegengleich Arm und Bein langsam strecken\n3. Lendenwirbelsäule bleibt am Boden, ausatmen beim Strecken","expl": "","dosage": "2–3x6–8 pro Seite","src": "Boyle/DNS"},{"id": "cr046","name": "Bear Plank / Quadruped Hover","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. Vierfüßlerstand, Zehen aufgestellt\n2. Knie 2–3 cm vom Boden lösen\n3. halten, ruhig durch die Nase atmen","expl": "","dosage": "3–5x15–20 Sek.","src": "DNS"},{"id": "cr047","name": "Pallof Press (half-kneeling)","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. halber Kniestand seitlich zum Kabel/Band\n2. Band vor der Brust nach vorn drücken, 2 Sek. halten\n3. Rumpf dreht nicht mit (Anti-Rotation)","expl": "","dosage": "2x8–10 pro Seite","src": "Boyle/Pallof"},{"id": "cr048","name": "Half-Kneeling Chop","type": "Bewegungsmuster","region": "Rumpf","desc": "1. halber Kniestand, Band/Kabel hoch seitlich\n2. diagonal von oben nach unten über das vordere Knie ziehen\n3. Oberkörper aufrecht, Becken stabil","expl": "","dosage": "2x8 pro Seite","src": "Cook/FMS"},{"id": "cr049","name": "Half-Kneeling Lift","type": "Bewegungsmuster","region": "Rumpf","desc": "1. halber Kniestand, Band/Kabel tief seitlich\n2. diagonal von unten nach oben über das hintere Knie ziehen\n3. Oberkörper aufrecht, Becken stabil","expl": "","dosage": "2x8 pro Seite","src": "Cook/FMS"},{"id": "cr050","name": "Turkish Get-Up (partial: to elbow)","type": "Bewegungsmuster","region": "Ganzkörper","desc": "1. Rückenlage, Arm mit (leichter) Kettlebell senkrecht, gleichseitiges Bein aufgestellt\n2. über den Ellbogen aufrichten, Blick zur Kettlebell\n3. kontrolliert zurück","expl": "","dosage": "3–5x pro Seite","src": "Cook/FMS"},{"id": "cr051","name": "Suitcase Carry","type": "Stabilität/Aktivierung","region": "Rumpf","desc": "1. einseitig Kettlebell/Hantel halten\n2. aufrecht gehen, Schultern waagerecht\n3. Rumpf neigt nicht zur Seite","expl": "","dosage": "2–3x20 m pro Seite","src": "Dan John/Boyle"},{"id": "cr052","name": "Split Squat Iso Hold","type": "Stabilität/Aktivierung","region": "Knie","desc": "1. Ausfallschritt-Position, hinteres Knie knapp über dem Boden\n2. Position halten, vorderes Knie über dem Fuß\n3. Oberkörper aufrecht","expl": "","dosage": "3x20–30 Sek. pro Seite","src": "Boyle"},{"id": "cr053","name": "Spanish Squat (Band)","type": "Stabilität/Aktivierung","region": "Knie","desc": "1. schweres Band hinter beiden Kniekehlen, an einem Pfosten befestigt\n2. Schienbeine senkrecht, nach hinten in die Hocke setzen\n3. halten","expl": "","dosage": "5x30–45 Sek.","src": "Patellasehnen-Reha"},{"id": "cr054","name": "Single-Leg Balance Reach (Y-Balance)","type": "Stabilität/Aktivierung","region": "Knie","desc": "1. Einbeinstand, Knie leicht gebeugt\n2. mit dem freien Fuß nach vorn, hinten-innen, hinten-außen tippen\n3. Knie bleibt über dem Fuß, Becken waagerecht","expl": "","dosage": "2x5 pro Richtung/Seite","src": "Plisky/Cook"},{"id": "cr055","name": "Short Foot Exercise","type": "Stabilität/Aktivierung","region": "Fuß/Sprunggelenk","desc": "1. sitzend oder stehend, Fuß flach\n2. Fußgewölbe aufbauen: Großzehenballen Richtung Ferse ziehen, Zehen bleiben lang\n3. halten","expl": "","dosage": "10x5 Sek. pro Seite","src": "Janda"},{"id": "cr056","name": "Toe Yoga","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. stehend\n2. Großzehe anheben, andere Zehen bleiben unten – dann umgekehrt\n3. langsam und kontrolliert","expl": "","dosage": "2x10","src": "Fuß-Reha"},{"id": "cr057","name": "Single-Leg Calf Raise (slow eccentric)","type": "Stabilität/Aktivierung","region": "Fuß/Sprunggelenk","desc": "1. Einbeinstand auf einer Stufe\n2. hochdrücken (1 Sek.), langsam absenken (3–4 Sek.)\n3. Knie gestreckt bzw. gebeugt (Soleus)","expl": "","dosage": "3x10–15 pro Seite","src": "Boyle"},{"id": "cr058","name": "Tibialis Raise","type": "Stabilität/Aktivierung","region": "Fuß/Sprunggelenk","desc": "1. Rücken an der Wand, Fersen ca. 30 cm vor der Wand\n2. Fußspitzen anheben und kontrolliert absenken","expl": "","dosage": "2–3x15–20","src": "Knees-over-Toes"},{"id": "cr059","name": "Banded Ankle Distraction","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. Band tief am Sprunggelenk (vorn), Zug nach hinten\n2. Fuß auf Box oder im halben Kniestand\n3. Knie über die Zehen nach vorn schieben, Ferse bleibt unten","expl": "","dosage": "2 Min. pro Seite","src": "Starrett"},{"id": "cr060","name": "Calf Smash (Ball/Roller)","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Wade auf Roller/Ball, anderes Bein darüberlegen\n2. Druck halten, Fuß beugen/strecken\n3. quer zur Faser bewegen","expl": "","dosage": "2 Min. pro Seite","src": "Starrett"},{"id": "cr061","name": "T-Spine Smash (Double Ball/Peanut)","type": "Selbstmassage","region": "Brustwirbelsäule","desc": "1. Rückenlage, Peanut-Ball neben der Wirbelsäule\n2. Arme vor der Brust kreuzen, Gesäß anheben\n3. kleine Crunches über dem Ball, Segment für Segment","expl": "","dosage": "2–3 Min.","src": "Starrett"},{"id": "cr062","name": "Side-Lying Windmill (Open Book with Reach)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Seitlage, oberes Knie auf Rolle\n2. oberen Arm in großem Bogen über den Kopf nach hinten führen\n3. Blick folgt der Hand, Knie bleibt unten","expl": "","dosage": "5–6x pro Seite","src": "Cook/Boyle"},{"id": "cr063","name": "Pec Smash (Ball on Wall)","type": "Selbstmassage","region": "Schulter","desc": "1. Ball zwischen Brustmuskel und Wand\n2. Druck halten, Arm langsam bewegen\n3. Hotspots 20–30 Sek. halten","expl": "","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr064","name": "Serratus Wall Slide (Foam Roller)","type": "Stabilität/Aktivierung","region": "Schulter","desc": "1. Unterarme auf einem Foam Roller an der Wand\n2. Roller nach oben rollen, Schulterblätter nach vorn-oben\n3. Rippen unten, kein Schulterhochziehen","expl": "","dosage": "2x8–10","src": "Cressey/Boyle"},{"id": "cr065","name": "Scap Push-Up","type": "Stabilität/Aktivierung","region": "Schulter","desc": "1. Liegestützposition (oder auf Knien)\n2. Arme gestreckt lassen, nur Schulterblätter zusammen- und auseinanderführen\n3. Rumpf stabil","expl": "","dosage": "2x10–12","src": "Boyle"},{"id": "cr066","name": "Band External Rotation (side)","type": "Stabilität/Aktivierung","region": "Schulter","desc": "1. Ellbogen 90° am Körper, Handtuch zwischen Arm und Rumpf\n2. Band nach außen drehen\n3. langsam zurück","expl": "","dosage": "2x12–15 pro Seite","src": "Reha-Standard"},{"id": "cr067","name": "Bottoms-Up Kettlebell Hold/Carry","type": "Stabilität/Aktivierung","region": "Schulter","desc": "1. Kettlebell kopfüber (Boden oben) vor der Schulter halten\n2. festes Greifen, Handgelenk gerade\n3. stehen oder langsam gehen","expl": "","dosage": "3x20–30 Sek. pro Seite","src": "Cook/Boyle"},{"id": "cr068","name": "Sleeper Stretch (gentle)","type": "Dehnung","region": "Schulter","desc": "1. Seitlage auf der zu dehnenden Schulter, Ellbogen 90° vor dem Körper\n2. mit der anderen Hand den Unterarm sanft Richtung Boden führen\n3. nur bis zum leichten Zug, schmerzfrei","expl": "","dosage": "3x30 Sek. pro Seite","src": "Reha-Standard"},{"id": "cr069","name": "Chin Tuck (supine/standing)","type": "Stabilität/Aktivierung","region": "Nacken","desc": "1. Rückenlage oder Stand an der Wand\n2. Kinn leicht nach hinten schieben („Doppelkinn“), Hinterkopf lang\n3. 5 Sek. halten","expl": "","dosage": "10x5 Sek.","src": "Janda"},{"id": "cr070","name": "Goblet Squat Prying","type": "Bewegungsmuster","region": "Hüfte","desc": "1. Kettlebell vor der Brust, tiefe Hocke\n2. Ellbogen drücken die Knie nach außen\n3. Becken sanft hin und her bewegen, Oberkörper aufrecht","expl": "","dosage": "3x30–45 Sek.","src": "Dan John"},{"id": "cr071","name": "Assisted Deep Squat (TRX/Band)","type": "Bewegungsmuster","region": "Hüfte","desc": "1. an TRX/Band festhalten\n2. kontrolliert in die tiefe Hocke, Fersen bleiben unten\n3. unten atmen, mit Hilfe aufstehen","expl": "","dosage": "2x8–10","src": "Cook/FMS"},{"id": "cr072","name": "Single-Leg RDL to Reach","type": "Bewegungsmuster","region": "Hüfte","desc": "1. Einbeinstand, Knie leicht gebeugt\n2. Hüftbeuge mit langem Rücken, freies Bein nach hinten\n3. mit der Gegenhand nach vorn-unten greifen, Becken waagerecht","expl": "","dosage": "2x6–8 pro Seite","src": "Boyle/Cook"},{"id": "cr073","name": "Half-Kneeling Hip Flexor + Overhead Reach","type": "Bewegungsmuster","region": "Hüfte","desc": "1. halber Kniestand, Gesäß anspannen\n2. gleichseitigen Arm über Kopf strecken und zur Gegenseite neigen\n3. Rippen unten, nicht ins Hohlkreuz","expl": "","dosage": "5–6 Atemzüge pro Seite","src": "Cook/FMS"},{"id": "cr074","name": "Overhead Rib Mobilization (Lacrosse Ball)","type": "Selbstmassage","region": "Brustwirbelsäule","desc": "1. Rückenlage, Füße aufgestellt, Lacrosse-Ball zwischen Schulterblatt und Wirbelsäule (oben beginnen)\n2. Fersen in den Boden, Becken anheben – der Ball drückt tief ins Gewebe\n3. gestreckten Arm über Kopf nach hinten führen, dann diagonal über den Körper zur Gegenhüfte\n4. Ellbogen bleibt gestreckt; Stelle für Stelle am Schulterblattrand nach unten wandern","expl": "Verbessert Schulterbeweglichkeit, steife Rippen/BWS, Schmerzen in Schulter, oberem Rücken und Nacken. Überkopf: obere Rippen; Drücken (Bankdrücken, Liegestütz): untere Rippen.","dosage": "≥ 30 Sek. pro Stelle, 15–20 Armschwünge","src": "Starrett S. 301"},{"id": "cr075","name": "Lat & Armpit Smash (Lacrosse Ball)","type": "Selbstmassage","region": "Schulter","desc": "1. Seitlage, Arm über Kopf gestreckt, Ball an der Achselhöhle (Ansatz Latissimus/Rotatorenmanschette)\n2. langsam auf die Seite rollen und Gewicht in den Ball sinken lassen\n3. pendelnd um die Achselhöhle bewegen; den ganzen Latissimus bis zum unteren Rücken abarbeiten","expl": "Verbessert Schulterfunktion und Stabilität über Kopf, lindert Schulterschmerzen. Variante: weicher größerer Ball oder Rolle.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 313"},{"id": "cr076","name": "Serratus Smash (Ball)","type": "Selbstmassage","region": "Schulter","desc": "1. Bauchlage seitlich, Arm zur Seite gestreckt, Ball etwas unterhalb der Achsel zwischen Latissimus und Brustmuskel\n2. mit so viel Gewicht wie erträglich langsam Richtung gestreckter Arm gleiten\n3. in alle Richtungen reiben; Hände in den Boden „schrauben“ (anspannen) und wieder lösen, Arm über die Matte gleiten lassen","expl": "Verbessert Werfen, Schmettern, Stoßen und Schwingen; lindert Schulterschmerzen. Bereich ist empfindlich – ggf. weicheren Ball nehmen. Test: Arme locker zur Seite schwingen vorher/nachher.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 316"},{"id": "cr077","name": "Banded Overhead Distraction (Starrett)","type": "Mobilisation","region": "Schulter","desc": "1. Band hoch befestigt, Handgelenk in die Schlaufe einhängen und beide Seiten der Schlaufe greifen\n2. mit der anderen Hand den Arm nach außen drehen (Handfläche oben, Daumen zeigt nach außen)\n3. Hüfte nach hinten schieben, Rumpf absenken – Arm bleibt über Kopf außenrotiert\n4. Position halten, anspannen/lösen (Contract-Relax); hinteres Bein strecken verstärkt","expl": "Für mangelnden Überkopf-Bewegungsumfang – Zeit in der Endposition unter Spannung verbringen.","dosage": "2 Min. pro Seite","src": "Starrett S. 317"},{"id": "cr078","name": "Banded Overhead Distraction – Elbow Hook","type": "Mobilisation","region": "Schulter","desc": "1. gestreckten Arm durch die Bandschlaufe stecken, Schlinge oberhalb des Ellbogens um den Oberarm\n2. Band mit der Hand von außen greifen, vom Pfosten wegtreten (Distraktion), Rippen nach unten\n3. mit der freien Hand den Ellbogen zum Kopf ziehen und leicht in die Knie gehen – Außenrotation halten","expl": "Ergänzung zur Überkopf-Distraktion: Ellbogen fixiert → tiefer in die Schulterflexion (Überkopf, Front Rack).","dosage": "2 Min. pro Seite","src": "Starrett S. 318"},{"id": "cr079","name": "Super Front Rack (Banded)","type": "Mobilisation","region": "Schulter","desc": "1. Handgelenk in die Bandschlaufe (Band tief/hinten), Handfläche nach oben, Schulter außenrotiert\n2. Schritt nach vorn und so drehen, dass der Rücken zum Band zeigt; Ellbogen hoch Richtung Front-Rack\n3. Rumpf aufrichten, Gesäß und Bauch fest (kein Hohlkreuz)\n4. mit der anderen Hand den Ellbogen von außen halten, Gewicht nach vorn verlagern","expl": "Verbessert Front-Rack- und Überkopfposition. Handfläche bleibt oben, Ellbogen darf nicht nach außen ausweichen.","dosage": "2 Min. pro Seite","src": "Starrett S. 320"},{"id": "cr080","name": "Banded Shoulder Extension / Internal Rotation","type": "Mobilisation","region": "Schulter","desc": "1. Bandschlaufe von vorn über die vordere Schulter (Deltamuskel), Arm auf den unteren Rücken legen; andere Hand fixiert das Handgelenk\n2. nach vorn lehnen – das Band zieht den Oberarmkopf in der Pfanne nach hinten\n3. Arm mit der anderen Hand quer über den Rücken ziehen, Kopf zur Gegenseite neigen","expl": "Verbessert Schulterstreckung und -innenrotation (Hängen, Drücken) aus stabiler Schulterposition.","dosage": "2 Min. pro Seite","src": "Starrett S. 330"},{"id": "cr081","name": "Banded Lateral Opener (Pec)","type": "Mobilisation","region": "Schulter","desc": "1. Hand seitlich in die Bandschlaufe (Band auf Schulterhöhe), Band auf Zug bringen\n2. Handfläche nach oben drehen (Außenrotation)\n3. Schulter zurück, Oberkörper vom Band wegdrehen – Brust und Schulter öffnen","expl": "Schnelle Vorbereitung für Druckübungen (Liegestütz, Bankdrücken): Brustmuskel in Streckung, Schulteraußenrotation.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 334"},{"id": "cr082","name": "Lateral Trunk Smash (Ball)","type": "Selbstmassage","region": "Rumpf","desc": "1. Seitlage, Ball zwischen Brustkorb und Hüftknochen (schräge Bauchmuskeln)\n2. Rumpf über den Ball drehen und so viel Gewicht wie erträglich abgeben\n3. auch am Rand des Hüftknochens reiben; alternativ stehend an der Wand","expl": "Lindert Rückenschmerzen, verbessert seitliche und Drehbeweglichkeit.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 356"},{"id": "cr083","name": "Classic Spinal Twist (Starrett)","type": "Mobilisation","region": "Rumpf","desc": "1. Rückenlage, Beine anziehen\n2. Knie zur Seite fallen lassen, gegenüberliegende Schulter bleibt am Boden\n3. Knie mit der Hand Richtung Boden drücken, anderen Arm ausstrecken, Kopf zur Gegenseite drehen\n(Variante: Band um den Oberschenkel zieht Richtung Füße)","expl": "Großflächig für den unteren Rücken; gut als Test vor/nach anderen Mobilisationen.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 356"},{"id": "cr084","name": "Seated Lateral Hip Opener","type": "Mobilisation","region": "Rumpf","desc": "1. Schneidersitz, einen Fuß auf das andere Knie ziehen\n2. Arm über Kopf führen und den Oberkörper in einer Ebene seitlich über die Hüfte neigen (nicht drehen)\n3. Oberschenkel und Hüfte der Gegenseite drücken nach unten","expl": "Lindert Schmerzen im unteren Rücken (schräge Bauchmuskeln, QL), verbessert Seitneigung.","dosage": "1 Min. pro Seite","src": "Starrett S. 357"},{"id": "cr085","name": "Side Opener (Barrel/Physio Ball)","type": "Mobilisation","region": "Rumpf","desc": "1. seitlich über ein Fass, einen Physioball oder Medizinball auf Hantelscheiben legen\n2. oberen Arm über Kopf führen und über das Gerät beugen\n3. Bauch fest (Midline), Oberkörper dabei nicht verdrehen","expl": "Mobilisiert die ganze Körperseite: schräge Bauchmuskeln, QL, Rippen, Hüfte.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 357"},{"id": "cr086","name": "Glute Smash & Floss (Lacrosse Ball)","type": "Selbstmassage","region": "Hüfte","desc": "1. Sitz, Lacrosse-Ball seitlich unter das Gesäß\n2. Hüfte nach außen drehen und Knie zur Matte fallen lassen, dann zurückführen\n3. zusätzlich langsam quer über den Ball rollen; Schmerzpunkte mit Anspannen/Lösen bearbeiten","expl": "Lindert Schmerzen in unterem Rücken und Hüfte. Test: nach 5 Min. im Stand beide Pobacken kneifen – die mobilisierte Seite kontrahiert stärker.","dosage": "ca. 5 Min. pro Gesäßhälfte","src": "Starrett S. 368"},{"id": "cr087","name": "Lateral Hip Smash (Ball)","type": "Selbstmassage","region": "Hüfte","desc": "1. Ball seitlich über dem Beckenkamm oben am Gesäßmuskel anlegen\n2. auf die Seite rollen, quer zur Faser arbeiten, viel Gewicht in den Ball\n3. weiter nach vorn Richtung Hüftbeuger rollen","expl": "Bearbeitet mittleren/kleinen Gesäßmuskel bis zum Hüftbeuger – lindert Schmerzen in unterem Rücken und Hüfte.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 370"},{"id": "cr088","name": "Single-Leg Flexion – External Rotation Bias (floor)","type": "Mobilisation","region": "Hüfte","desc": "1. Kniestand, Fuß außen neben die Hand stellen, Schienbein senkrecht\n2. Fuß mit der Hand fixieren, hinteres Bein strecken, Knie nach außen kippen; Hüfte aktiv zum Boden, kleine Pendelbewegungen\n3. Oberkörper zum gestreckten Bein drehen bzw. Ellbogen ablegen und Knie weiter nach außen drücken\n4. Hüfte nach hinten ziehen (Rückseite/Hamstrings), dann wieder nach vorn","expl": "Bereitet die tiefe Kniebeuge vor. Fuß bleibt am Boden. Mit Band um die Leiste (seitlich/nach hinten) deutlich effektiver.","dosage": "2 Min. pro Seite","src": "Starrett S. 370"},{"id": "cr089","name": "Single-Leg Flexion – External Rotation Bias (box)","type": "Mobilisation","region": "Hüfte","desc": "1. Fuß auf einen Kasten, mit der Hand festhalten; Unterschenkel senkrecht, Fuß nicht kippen\n2. hinteres Bein nach hinten in die Streckung rutschen lassen, Knie nach außen fallen lassen\n3. Oberkörper zum Knie drehen, Brust zum Kasten absenken\n4. Gesäß nach hinten (Rückseite), dann wieder nach vorn","expl": "Wenn am Boden das hintere Bein nicht streckbar ist (steife Hüften). Mit Band um die Leiste möglich.","dosage": "2 Min. pro Seite","src": "Starrett S. 372"},{"id": "cr090","name": "Hip External Rotation with Flexion (Pigeon, floor)","type": "Mobilisation","region": "Hüfte","desc": "1. Sitz, Beine gestreckt; zur Seite neigen, hinteres Bein nach hinten, Unterschenkel quer vor den Körper\n2. Hand aufs Knie, Arme strecken, Schultern zurück\n3. Brust mit geradem Rücken Richtung Boden senken\n4. Fuß blockieren, Oberkörper nach links/rechts drehen (Bauchnabel über den Fuß)","expl": "Fokus Außenrotation + Beugung. Nicht mit rundem Rücken. Bei Knieschmerzen abbrechen und Option am Kasten wählen.","dosage": "2 Min. pro Seite","src": "Starrett S. 373"},{"id": "cr091","name": "Hip External Rotation – Knee Drop (floor)","type": "Mobilisation","region": "Hüfte","desc": "1. Ausgangsposition wie einseitiges Beinbeugen, Unterschenkel senkrecht, Fuß mit der Hand halten, anderes Bein hinten\n2. mit der Hand am Boden balancieren, Knie zur Seite und Fuß auf die Außenkante fallen lassen\n3. Oberkörper wegdrehen und Knie mit der Hand weiter nach außen drücken, dann zur anderen Seite drehen","expl": "Für sehr steife Sportler mit Knieproblemen in der Pigeon-Position.","dosage": "2 Min. pro Seite","src": "Starrett S. 374"},{"id": "cr092","name": "Hip External Rotation with Flexion (box)","type": "Mobilisation","region": "Hüfte","desc": "1. Unterschenkel quer auf einen Kasten legen, anderes Bein nach hinten strecken, Fuß festhalten\n2. Knie niederdrücken, Oberkörper mit geradem Rücken nach vorn beugen (vor- und zurückgehen)\n3. Oberkörper zum Fuß bzw. zum Knie drehen\n4. fortgeschritten: hinteres Knie zum Boden, Oberkörper auf das Bein legen","expl": "Bei Schmerzen an der Knieaußenseite oder Problemen am Boden – mehr Hüftrotation, aggressivere Beugebelastung.","dosage": "2 Min. pro Seite","src": "Starrett S. 375"},{"id": "cr093","name": "Hip External Rotation – Half on Box","type": "Mobilisation","region": "Hüfte","desc": "1. nur mit einer Gesäßhälfte auf den Kasten setzen, Fuß über die Kante hängen lassen (schont das Knie)\n2. aus der Hüfte nach vorn beugen, Oberkörper zum Knie führen","expl": "Für sehr steife Hüften – Knie bleibt entlastet.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 376"},{"id": "cr094","name": "Knee-to-Chest Hip Flexion (box)","type": "Mobilisation","region": "Hüfte","desc": "1. mit einer Gesäßhälfte auf den Kasten, Arme um das Schienbein (schützt das Knie)\n2. Knie zur Brust ziehen\n3. Oberkörper zum angewinkelten Bein drehen und auf den Kasten absenken","expl": "Außenrotation mit Beugung ohne Kniebelastung.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 376"},{"id": "cr095","name": "Olympic Wall Squat with External Rotation","type": "Mobilisation","region": "Hüfte","desc": "1. Rückenlage, Gesäß nah an Wand/Kasten, Füße schulterbreit an der Wand (Unterschenkel parallel zum Boden)\n2. rechten Unterschenkel aufs linke Knie legen\n3. Fußrücken mit der Hand nach unten halten, Knie mit der anderen Hand vom Körper wegdrücken","expl": "Verbessert Hüftbeugung und Außenrotation; mit Band an Hüfte oder Knie verstärkbar.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 376"},{"id": "cr096","name": "Seated Hip Mobilization (Office Chair)","type": "Mobilisation","region": "Hüfte","desc": "1. aufrecht auf einen Stuhl, rechten Fuß über das linke Knie\n2. Bein aktiv nach außen drehen, mit geradem Rücken aus der Hüfte nach vorn neigen\n3. Fuß fixieren, Knie nach unten drücken (Arm gestreckt)\n4. Rumpf zur Hand drehen, Brustkorb zum Knie","expl": "Für lange Sitzzeiten (Schule, Büro): Hüftaußenrotation und hintere Kette im Sitzen.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 377"},{"id": "cr097","name": "Quad Smash (Hard Roller)","type": "Selbstmassage","region": "Knie","desc": "1. Seitlage, Oberschenkel auf harter Rolle, Fuß in die Matte, Arme stützen\n2. langsam Richtung Bauchlage rollen – Druckwelle quer zur Faser\n3. in Bauchlage: Contract-Relax und kleine Pendelbewegungen\n4. Ferse zum Gesäß ziehen, auf der Stelle bleiben bis sie schmerzfrei ist, dann weiter","expl": "Rolle am Boden = mehr Kontrolle über den Druck.","dosage": "2 Min. pro Seite","src": "Starrett S. 386"},{"id": "cr098","name": "Quad Smash (Barbell)","type": "Selbstmassage","region": "Knie","desc": "1. Sitz, Hantelstange (Scheibenaufnahme) auf den oberen Oberschenkel, mit den Händen nach unten drücken\n2. längs mit großer Druckwelle über den Muskel rollen, bei Verhärtungen querrollen + Contract-Relax\n3. Bein nach innen drehen und weitere Bereiche bearbeiten","expl": "Stumpfer, tiefer Druck – besonders wirksam im hüftnahen Bereich.","dosage": "2 Min. pro Seite","src": "Starrett S. 386"},{"id": "cr099","name": "Banded Hip Extension (kneeling)","type": "Mobilisation","region": "Hüfte","desc": "1. Kniestand, Band unterhalb des Gesäßes um das hintere Bein, Zug nach hinten; Fuß leicht nach innen\n2. Gesäß und Bauch anspannen (kein Hohlkreuz)\n3. Gewicht langsam nach vorn über das Knie verlagern – nur die Hüfte geht nach vorn\n4. hinteren Fuß mit einem Gewicht fixieren","expl": "Öffnet Hüftvorderseite und Gelenkkapsel; lindert Schmerzen in unterem Rücken und Hüfte.","dosage": "2 Min. pro Seite","src": "Starrett S. 390"},{"id": "cr100","name": "Banded Lunge Hip Extension","type": "Mobilisation","region": "Hüfte","desc": "1. Band unterhalb des Gesäßes um das hintere Bein, Zug nach hinten; Gesäß und Rumpf fest\n2. hinteres Knie zum Boden senken, vorderer Unterschenkel senkrecht, Oberkörper aufrecht\n3. über das Standbein beide Knie strecken und aufstehen","expl": "Dynamisch – gut als Trainings- oder Wettkampfvorbereitung (Haltung wie Split Jerk).","dosage": "8–10x pro Seite","src": "Starrett S. 391"},{"id": "cr101","name": "Couch Stretch (Starrett)","type": "Mobilisation","region": "Hüfte","desc": "1. Vierfüßlerstand, Füße gegen Kasten/Wand\n2. ein Bein zurückrutschen, Knie direkt an die Wand, Unterschenkel und Fuß plan an der Wand\n3. Gesäß anspannen, anderes Bein nach vorn aufstellen (Unterschenkel senkrecht)\n4. Hüfte nach unten drücken, Oberkörper langsam aufrichten","expl": "Hüftbeuger und Quadrizeps. Typische Fehler: Knie rutscht zur Seite, Rücken wird überstreckt – Gesäß immer angespannt, bei Bedarf Kasten zum Abstützen.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 391"},{"id": "cr102","name": "Super Couch Stretch (Banded)","type": "Mobilisation","region": "Hüfte","desc": "1. Band unterhalb des Gesäßes um das hintere Bein, nach hinten spannen, vorderen Fuß aufstellen\n2. Knie neben dem Kasten auf den Boden, Unterschenkel und Fuß plan an die Kastenseite\n3. Gesäß maximal anspannen, Hüfte Richtung Boden drücken\n4. mit aktivem Gesäß und Rumpf langsam aufrichten","expl": "Deutlich aggressiver – nur wenn der normale Couch Stretch gut gelingt.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 393"},{"id": "cr103","name": "Hamstring Smash – Small Ball (box)","type": "Selbstmassage","region": "Hüfte","desc": "1. Sitz auf Kasten, Lacrosse-Ball unter den Oberschenkel, viel Gewicht\n2. bei Verhärtung Bein mehrmals strecken und beugen, auch quer über den Ball bewegen\n3. Gewicht vor/zurück verlagern und den Muskel der Länge nach bearbeiten","expl": "Hintere Oberschenkelmuskulatur – Pendelbewegungen auf den Verhärtungen.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 405"},{"id": "cr104","name": "Hamstring Smash – Large Ball (box)","type": "Selbstmassage","region": "Hüfte","desc": "1. Softball/größeren Ball unter die Oberschenkelrückseite (auch Außenseite/IT-Band-Bereich)\n2. durch Drehen viel Gewicht auf den Ball\n3. Strecken/Beugen (Floss) oder quer rollen – von außen bis zu den Adduktoren","expl": "Breitere Druckwellen über die gesamte Rückseite.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 405"},{"id": "cr105","name": "Banded Hamstring Hinge (standing)","type": "Mobilisation","region": "Hüfte","desc": "1. Band um den Oberschenkel nahe der Hüftbeuge, Schritt nach vorn (Zug nach hinten)\n2. Bauch fest, Rücken gerade, aus der Hüfte maximal nach vorn/unten beugen\n3. wieder aufrichten; Knie gestreckt, Gewicht über der Ferse","expl": "Hintere Kette im Stehen – Belastung wie beim Kreuzheben.","dosage": "10x pro Seite","src": "Starrett S. 410"},{"id": "cr106","name": "Banded Hamstring – Foot on Box","type": "Mobilisation","region": "Hüfte","desc": "1. Band um den Oberschenkel nahe der Hüftbeuge, Fuß auf einen Kasten\n2. Bein strecken, Hüfte kräftig nach hinten schieben (Fuß flach, erst beim Durchstrecken Ballen anheben)\n3. Knie langsam beugen, Gewicht nach vorn – im Wechsel beugen und strecken","expl": "Oberster Bereich der Oberschenkelrückseite in gebeugter Hüftstellung (wichtig für Kniebeugen).","dosage": "2 Min. pro Seite","src": "Starrett S. 410"},{"id": "cr107","name": "Supine Banded Hamstring Mobilization","type": "Mobilisation","region": "Hüfte","desc": "1. Rückenlage, Band um den Oberschenkel nahe der Hüftbeuge (anderes Ende um Fuß oder Pfosten), Knie zur Brust\n2. Oberschenkel von hinten über dem Knie umfassen, Sprunggelenk greifen\n3. Knie strecken und beugen; gegen den Zug der Hände anspannen/lösen; Bein nach innen/außen führen\n(ohne Reichweite: Band mittig um die Fußsohle)","expl": "Rücken bleibt unbelastet und neutral. Nie mit gekrümmtem Rücken zum Fuß ziehen.","dosage": "2 Min. pro Seite","src": "Starrett S. 411"},{"id": "cr108","name": "Knee Gapping & Smash (Lacrosse Ball)","type": "Selbstmassage","region": "Knie","desc": "1. Sitz, Lacrosse-Ball innen (Option 2: außen) hinter das Knie\n2. Ferse zum Gesäß ziehen und Unterschenkel mit beiden Händen an den Oberschenkel pressen\n3. Fuß in alle Richtungen bewegen\n4. mehr Druck: Fuß auf den Boden, Gesäß zur Ferse schieben\n(Variante: Doppelball/Gemini erreicht innen + außen zugleich)","expl": "Hintere Oberschenkel- und obere Wadenmuskulatur; bei Knieschmerzen und eingeschränkter Kniebeugung/-streckung.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 415"},{"id": "cr109","name": "Plantar Smash (Roller/Soft Ball)","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Fuß auf eine Rolle oder einen weichen Ball stellen\n2. unter Druck hin- und herdrehen (wie eine Zigarette ausdrücken)\n3. Zehen über die Rolle/den Ball beugen","expl": "Gleitfähigkeit der Fußsohle, Beweglichkeit von Vorfuß und Zehen.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 438"},{"id": "cr110","name": "Forefoot Smash (Lacrosse Ball)","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Lacrosse-Ball an der Fußinnenseite unter das Gewölbe, Außenkante hat Bodenkontakt\n2. mit dem Vorfuß nach hinten gegen den Ball drücken, Fußgelenke stabil\n3. Gewicht auf den Ball, über die Innenseite Scherkraft erzeugen\n(Ergänzung: im Sitz den Vorfuß mit den Händen gegen die Ferse bewegen)","expl": "Für stabiles Fußgewölbe und Sprunggelenkfunktion; bei Fußschmerzen/Plantarfasziitis.","dosage": "1–2 Min. pro Seite","src": "Starrett S. 438"},{"id": "cr111","name": "T-Spine Overhead Extension Smash (Double Ball)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Rückenlage, Doppelball (zwei getapte Lacrosse-Bälle) quer unter der Brustwirbelsäule\n2. Arme gestreckt über den Kopf, Gesäß am Boden\n3. in der Ausatmung über den Ball nach hinten strecken, Segment für Segment weiterrücken","expl": "","dosage": "2–3 Min.","src": "Starrett"},{"id": "cr112","name": "Rib / T-Spine Smash (Single Ball, side)","type": "Selbstmassage","region": "Brustwirbelsäule","desc": "1. Rückenlage, Ball zwischen Wirbelsäule und Schulterblatt\n2. Arm über die Brust ziehen, Gesäß anheben\n3. Arm langsam nach oben/unten bewegen, Hotspots halten","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr113","name": "Lat / Teres Smash (Roller)","type": "Selbstmassage","region": "Schulter","desc": "1. Seitlage, Foam Roller unter der Achsel, Arm über Kopf\n2. vom Achselbereich bis zur Rippe rollen\n3. Daumen zur Decke / zum Boden drehen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "2 Min. pro Seite","src": "Starrett"},{"id": "cr114","name": "Overhead Bench Lat Stretch (Elbows on Bench)","type": "Mobilisation","region": "Schulter","desc": "1. Kniestand vor der Bank, Ellbogen auf der Bank, Stab/Hände über dem Kopf zusammen\n2. Gesäß Richtung Fersen\n3. Brust absinken lassen, Rippen unten halten","expl": "","dosage": "2 Min.","src": "Starrett"},{"id": "cr115","name": "Forearm Smash (Ball/Roller)","type": "Selbstmassage","region": "Handgelenk/Ellbogen","desc": "1. Unterarm auf Ball oder Roller, andere Hand gibt Druck\n2. Hand öffnen/schließen, Handgelenk kreisen\n3. Unterarmbeuger und -strecker bearbeiten","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr116","name": "Psoas Smash (Ball)","type": "Selbstmassage","region": "Rumpf","desc": "1. Bauchlage, weicher Ball neben dem Bauchnabel (seitlich, unterhalb der Rippen)\n2. in den Ball atmen, langsam Gewicht abgeben\n3. Knie beugen/strecken, Bein seitlich pendeln – bei Unwohlsein sofort abbrechen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr117","name": "QL Smash (Ball)","type": "Selbstmassage","region": "Rumpf","desc": "1. Rückenlage, Ball zwischen unterster Rippe und Beckenkamm\n2. Knie angewinkelt, Becken leicht zur Ballseite\n3. Knie langsam zur Seite fallen lassen und zurück","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr118","name": "Abdominal Smash (Soft Ball)","type": "Selbstmassage","region": "Rumpf","desc": "1. Bauchlage auf weichem Ball (oder kleinem Gymnastikball)\n2. tief in den Ball atmen, Spannung lösen\n3. langsam kleine Positionen wechseln","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "2 Min.","src": "Starrett"},{"id": "cr119","name": "Banded Lateral Hip Distraction","type": "Mobilisation","region": "Hüfte","desc": "1. Band um die Leiste, Zug seitlich nach außen\n2. halber Kniestand, Knie nach innen fallen lassen (Innenrotation)\n3. Position wechseln, pendeln","expl": "","dosage": "2 Min. pro Seite","src": "Starrett"},{"id": "cr120","name": "Banded Pigeon (Posterior Hip Distraction)","type": "Mobilisation","region": "Hüfte","desc": "1. Band um die Leiste, Zug nach hinten\n2. Pigeon-Position auf Box oder Boden\n3. Hüfte nach hinten schieben, Oberkörper nach vorn neigen","expl": "","dosage": "2 Min. pro Seite","src": "Starrett"},{"id": "cr121","name": "Super Frog","type": "Mobilisation","region": "Hüfte","desc": "1. Bauchlage, Knie weit nach außen gebeugt (Frosch)\n2. Becken flach am Boden\n3. mit der Atmung tiefer in die Position sinken","expl": "","dosage": "2 Min.","src": "Starrett"},{"id": "cr122","name": "Adductor Smash (Roller)","type": "Selbstmassage","region": "Hüfte","desc": "1. Bauchlage, ein Knie seitlich angewinkelt auf dem Roller (Innenschenkel)\n2. vom Knie bis zur Leiste rollen\n3. Knie beugen/strecken","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "2 Min. pro Seite","src": "Starrett"},{"id": "cr123","name": "Suprapatellar Pocket Smash (Ball)","type": "Selbstmassage","region": "Knie","desc": "1. Bauchlage, Ball knapp oberhalb der Kniescheibe\n2. Knie beugen und strecken\n3. kleine Positionen weiter nach innen/außen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr124","name": "Voodoo Floss Knee (Compression Band)","type": "Mobilisation","region": "Knie","desc": "1. Kompressionsband mit 50 % Zug um das Knie wickeln\n2. 10–15 tiefe Kniebeugen bzw. Beugen/Strecken\n3. Band nach max. 2 Min. lösen (Haut wird kurz rot)","expl": "","dosage": "max. 2 Min.","src": "Starrett"},{"id": "cr125","name": "Banded Heel Cord Mobilization","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. Band um die Ferse, Zug nach hinten\n2. Fuß auf Box, Knie über die Zehen schieben\n3. Ferse bleibt unten, pendeln","expl": "","dosage": "2 Min. pro Seite","src": "Starrett"},{"id": "cr126","name": "Upper Trap Smash (Ball on Wall/Bar)","type": "Selbstmassage","region": "Nacken","desc": "1. Ball zwischen Wand und oberem Trapez (oder unter Stange)\n2. in die Wand lehnen, Druck dosieren\n3. Arm langsam heben/senken, Kopf zur Gegenseite neigen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr127","name": "First Rib Mobilization (Ball)","type": "Mobilisation","region": "Schulter","desc": "1. Ball oberhalb des Schulterblatts am Übergang Nacken/Schulter, gegen die Wand\n2. tief einatmen, beim Ausatmen Arm über Kopf führen\n3. Kopf leicht zur Gegenseite","expl": "","dosage": "1–2 Min. pro Seite","src": "Starrett"},{"id": "cr128","name": "Banded Squat Distraction","type": "Mobilisation","region": "Hüfte","desc": "1. Band um die Hüften an fester Stange, Zug nach hinten\n2. tiefe Hocke, Ellbogen drücken die Knie nach außen\n3. in der Position pendeln","expl": "","dosage": "2 Min.","src": "Starrett"},{"id": "cr129","name": "Foam Rolling – Glutes","type": "Selbstmassage","region": "Hüfte","desc": "1. Sitz auf dem Roller, Bein überkreuzt (Knöchel aufs Knie)\n2. zur Seite des überkreuzten Beins kippen\n3. langsam rollen, Hotspots 20–30 Sek. halten","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr130","name": "Foam Rolling – Lateral Thigh (IT-Band Area)","type": "Selbstmassage","region": "Hüfte","desc": "1. Seitlage auf dem Roller, oberes Bein vorn aufgestellt\n2. von Hüfte bis knapp über das Knie rollen\n3. Druck über das obere Bein dosieren","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr131","name": "Foam Rolling – Adductors","type": "Selbstmassage","region": "Hüfte","desc": "1. Bauchlage, Bein seitlich angewinkelt auf dem Roller\n2. vom Knie bis zur Leiste rollen\n3. Hotspots halten, Knie beugen/strecken","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr132","name": "Foam Rolling – Hip Flexors","type": "Selbstmassage","region": "Hüfte","desc": "1. Bauchlage, Roller knapp unterhalb des Beckenkamms\n2. leicht zur Seite drehen, kleine Bewegungen\n3. Knie beugen/strecken","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1 Min. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr133","name": "Foam Rolling – Lats","type": "Selbstmassage","region": "Schulter","desc": "1. Seitlage, Roller unter der Achsel, Arm über Kopf\n2. bis zur Mitte des Brustkorbs rollen\n3. Oberkörper leicht vor- und zurückdrehen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr134","name": "Foam Rolling – Upper Back (Rhomboids)","type": "Selbstmassage","region": "Brustwirbelsäule","desc": "1. Rückenlage, Roller unter den Schulterblättern\n2. Arme vor der Brust kreuzen, Gesäß anheben\n3. langsam zwischen den Schulterblättern rollen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1–2 Min.","src": "Triggerball/Foam Roller"},{"id": "cr135","name": "Foam Rolling – Tibialis Anterior","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Vierfüßlerstand, Schienbein-Außenseite auf dem Roller\n2. vom Knöchel bis unterhalb des Knies rollen\n3. Fuß kreisen auf Hotspots","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1 Min. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr136","name": "Ball Release – Peroneals (Lateral Calf)","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Seitlage oder Sitz, Ball an der Außenseite der Wade\n2. Druck mit dem anderen Bein dosieren\n3. Fuß nach innen/außen drehen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "1 Min. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr137","name": "Ball Release – Piriformis/Deep Glute","type": "Selbstmassage","region": "Hüfte","desc": "1. Sitz auf dem Tennis-/Lacrosse-Ball (Gesäßmitte, leicht außen)\n2. Bein überkreuzen\n3. Hotspot halten, Knie langsam nach innen/außen bewegen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60–90 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr138","name": "Ball Release – Infraspinatus (Wall)","type": "Selbstmassage","region": "Schulter","desc": "1. Ball zwischen Wand und Schulterblatt (Mitte/außen)\n2. Druck über das Anlehnen dosieren\n3. Arm vor der Brust kreuzen bzw. Hand nach oben/unten drehen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60–90 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr139","name": "Ball Release – Between Shoulder Blades (Wall)","type": "Selbstmassage","region": "Brustwirbelsäule","desc": "1. Ball zwischen Wirbelsäule und Schulterblatt an der Wand\n2. leicht in die Knie gehen, um die Position zu wechseln\n3. Arm über die Brust ziehen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60–90 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr140","name": "Ball Release – Pec Minor (Wall)","type": "Selbstmassage","region": "Schulter","desc": "1. Ball unterhalb des Schlüsselbeins, nahe der Schulter, gegen die Wand\n2. Druck dosieren\n3. Arm langsam nach oben und hinten führen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr141","name": "Ball Release – Levator Scapulae (Wall)","type": "Selbstmassage","region": "Nacken","desc": "1. Ball am oberen inneren Schulterblattwinkel gegen die Wand\n2. Kopf zur Gegenseite neigen und drehen\n3. Hotspot halten, ruhig atmen","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr142","name": "Ball Release – Lower Back/Erector (Wall)","type": "Selbstmassage","region": "Rumpf","desc": "1. Ball neben der Lendenwirbelsäule (nicht auf der Wirbelsäule) gegen die Wand\n2. leicht in die Knie gehen, um zu rollen\n3. Hotspots halten","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60–90 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr143","name": "Ball Release – Adductors (Seated)","type": "Selbstmassage","region": "Hüfte","desc": "1. Sitz, Ball zwischen Innenschenkel und Boden bzw. Bank\n2. Druck mit den Händen dosieren\n3. Knie beugen/strecken","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr144","name": "Ball Release – Forearm Extensors (Table)","type": "Selbstmassage","region": "Handgelenk/Ellbogen","desc": "1. Unterarm auf dem Tisch, Ball darauf, andere Hand drückt\n2. Handgelenk beugen/strecken\n3. Hotspots halten","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr145","name": "Ball Release – Calf (Seated)","type": "Selbstmassage","region": "Fuß/Sprunggelenk","desc": "1. Sitz, Ball unter der Wade, anderes Bein darüber\n2. Fuß beugen/strecken\n3. Position Richtung Kniekehle verschieben","expl": "Trigger-Hinweis: Druck ca. 6–7 von 10, Hotspot 20–30 Sek. halten und ruhig ausatmen; nicht auf Knochen, Gelenke, Nerven oder akut entzündete Stellen.","dosage": "60–90 Sek. pro Seite","src": "Triggerball/Foam Roller"},{"id": "cr146","name": "T-Spine Rotation (standing)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. hüftbreiter Stand, leichte Hüftbeuge\n2. einen Arm nach oben aufdrehen, Blick folgt der Hand\n3. Becken bleibt ruhig","expl": "","dosage": "5-7x pro Seite","src": "FT"},{"id": "cr147","name": "Hip Circles (single leg standing)","type": "Mobilisation","region": "Hüfte","desc": "1. Einbeinstand (bei Bedarf festhalten)\n2. freies Knie anheben und große Kreise nach außen ziehen\n3. Becken bleibt ruhig, Richtung wechseln","expl": "","dosage": "7-10x pro Seite","src": "FT"},{"id": "cr148","name": "Knee to Wall","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. Schrittstellung vor der Wand, vorderer Fuß 5–10 cm entfernt\n2. Knie über die Zehen zur Wand führen, Ferse bleibt am Boden\n3. Abstand vergrößern, sobald es leicht geht","expl": "","dosage": "7-10x pro Seite","src": "FT"},{"id": "cr149","name": "Ankle Circles (half-kneeling, band-assisted)","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. halber Kniestand, Band vorn um das Sprunggelenk, Zug nach hinten\n2. Oberkörper über den vorderen Oberschenkel\n3. Knie in halben Kreisen über die Zehen schieben, Ferse bleibt unten","expl": "","dosage": "7-10x pro Richtung","src": "BER"},{"id": "cr150","name": "Heel Sit","type": "Dehnung","region": "Fuß/Sprunggelenk","desc": "1. Fersensitz, Fußrücken flach am Boden\n2. aufrecht sitzen, Hände neben den Knien\n3. leicht nach hinten wippen, entspannt atmen","expl": "","dosage": "90-120sek","src": "BER"},{"id": "cr151","name": "Ankle Figure-8 (single leg standing)","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. Einbeinstand (bei Bedarf festhalten)\n2. freien Fuß in einer liegenden Acht kreisen\n3. Richtung wechseln, Seite wechseln","expl": "","dosage": "7-10x pro Richtung","src": "BER"},{"id": "cr152","name": "90/90 Hip Switch","type": "Mobilisation","region": "Hüfte","desc": "1. Sitz mit beiden Knien 90° zur gleichen Seite\n2. Hände hinten abstützen\n3. Knie kontrolliert zur anderen Seite ablegen, Oberkörper lang","expl": "","dosage": "7-10x pro Seite","src": "FT"},{"id": "cr153","name": "Shin Box Get-Up","type": "Mobilisation","region": "Hüfte","desc": "1. 90/90-Sitz\n2. über das vordere Knie in den hohen Kniestand aufrichten (Gesäß anspannen)\n3. kontrolliert zurück, Seite wechseln","expl": "","dosage": "5-7x pro Seite","src": "FT"},{"id": "cr154","name": "90/90 Hip Switch (advanced)","type": "Mobilisation","region": "Hüfte","desc": "1. 90/90-Sitz ohne Hände (Arme nach vorn)\n2. Knie zur anderen Seite wechseln\n3. Oberkörper bleibt aufrecht","expl": "","dosage": "7-10x pro Seite","src": "BER"},{"id": "cr155","name": "Hip Rotation (quadruped)","type": "Mobilisation","region": "Hüfte","desc": "1. Vierfüßlerstand\n2. ein Knie anheben und große Kreise mit der Hüfte zeichnen\n3. Rumpf bleibt ruhig, beide Richtungen","expl": "","dosage": "7-10x pro Seite","src": "BER"},{"id": "cr156","name": "Hip Rotation (single leg standing)","type": "Mobilisation","region": "Hüfte","desc": "1. Einbeinstand, Hände in die Hüfte\n2. freies Knie auf 90° heben\n3. Knie nach außen öffnen und nach innen schließen, Becken bleibt ruhig","expl": "","dosage": "7-10x pro Seite","src": "FT"},{"id": "cr157","name": "Hip Flexor (half-kneeling)","type": "Mobilisation","region": "Hüfte","desc": "1. halber Kniestand, Band um die Leiste des hinteren Beins (Zug nach vorn)\n2. Gesäß anspannen, Becken nach hinten kippen\n3. Hüfte rhythmisch nach vorn schieben","expl": "","dosage": "7-10x pro Seite","src": "BER"},{"id": "cr158","name": "Hip Flexor Stretch (half-kneeling)","type": "Dehnung","region": "Hüfte","desc": "1. halber Kniestand\n2. hinteren Fuß mit der Hand Richtung Gesäß ziehen\n3. Gesäß anspannen, Becken nach hinten kippen, Rippen unten","expl": "","dosage": "90-120sek. pro Seite","src": "FMS"},{"id": "cr159","name": "Hip-Flexor Stretch (half-kneeling, assisted)","type": "Dehnung","region": "Hüfte","desc": "1. halber Kniestand, Band um den hinteren Oberschenkel (Zug nach vorn)\n2. Gesäß anspannen, Becken nach hinten kippen\n3. Position halten und ruhig atmen","expl": "","dosage": "90-120sek pro Seite","src": "BER"},{"id": "cr160","name": "Adductor Rock-Back","type": "Mobilisation","region": "Hüfte","desc": "1. Vierfüßlerstand, ein Bein seitlich gestreckt\n2. Rücken flach\n3. Hüfte Richtung Ferse zurückschieben und wieder nach vorn","expl": "","dosage": "7-10x pro Seite","src": "FT"},{"id": "cr161","name": "90/90 Glute Stretch","type": "Dehnung","region": "Hüfte","desc": "1. 90/90-Sitz\n2. Oberkörper lang über das vordere Schienbein neigen\n3. Zug im Gesäß halten, ruhig atmen","expl": "","dosage": "90-120sek. pro Seite","src": "BER"},{"id": "cr162","name": "Hip Rotation (half-kneeling)","type": "Mobilisation","region": "Hüfte","desc": "1. halber Kniestand\n2. vorderes Knie mit der gleichseitigen Hand nach außen drücken\n3. federnd, Fuß bleibt flach","expl": "","dosage": "7–10x pro Seite","src": "BER"},{"id": "cr163","name": "Scorpion","type": "Mobilisation","region": "Hüfte","desc": "1. Bauchlage, Arme seitlich ausgestreckt\n2. ein Bein anheben und zur Gegenhand rüberführen\n3. Schultern bleiben am Boden, keine Überstreckung im unteren Rücken","expl": "","dosage": "5-7x pro Seite","src": "FT"},{"id": "cr164","name": "Cat-Camel (quadruped)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Vierfüßlerstand\n2. Rücken Wirbel für Wirbel rund machen (Katzenbuckel)\n3. dann Wirbel für Wirbel ins Hohlkreuz, langsam","expl": "","dosage": "5–7x","src": "FMS"},{"id": "cr165","name": "Child's Pose","type": "Dehnung","region": "Brustwirbelsäule","desc": "1. Fersensitz, Oberkörper auf die Oberschenkel ablegen\n2. Arme nach vorn strecken oder neben den Körper legen\n3. in den Rücken atmen","expl": "","dosage": "90-120sek","src": "BER"},{"id": "cr166","name": "T-Spine Rotation (heel sit)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Fersensitz, Unterarm vor den Knien am Boden\n2. andere Hand an den Hinterkopf\n3. Ellbogen in der Ausatmung zur Decke aufdrehen","expl": "","dosage": "5-7x pro Seite","src": "BER"},{"id": "cr167","name": "T-Spine Rotation (Windmill)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Grätschstand, Oberkörper vorgeneigt, Arme seitlich\n2. mit der Hand zum gegenüberliegenden Fuß greifen\n3. anderer Arm zeigt zur Decke, Seite wechseln","expl": "","dosage": "5-7x pro Seite","src": "BER"},{"id": "cr168","name": "Open Book (side-lying)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Seitlage, Knie 90° übereinander, Arme nach vorn\n2. oberen Arm in der Ausatmung nach hinten öffnen\n3. Knie bleiben zusammen, Blick folgt der Hand","expl": "","dosage": "5-7x pro Seite","src": "FT"},{"id": "cr169","name": "Bench Thoracic Extension","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Kniestand vor der Bank, Ellbogen auf der Bank, Hände hinter dem Kopf\n2. Gesäß Richtung Fersen\n3. Brust in der Ausatmung absinken lassen","expl": "","dosage": "5-7x","src": "FT"},{"id": "cr170","name": "Wall Angels","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Rücken, Gesäß und Kopf an der Wand, Füße etwas vor der Wand\n2. Arme im „W“ an der Wand\n3. Arme nach oben schieben und zurück, Rippen unten","expl": "","dosage": "7–10x","src": "FMS"},{"id": "cr171","name": "Floor Angels","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Rückenlage, Knie angestellt\n2. Arme in „W“-Position am Boden\n3. Arme am Boden nach oben schieben und zurück, Kontakt halten","expl": "","dosage": "7–10x","src": "BER"},{"id": "cr172","name": "Shoulder Around-the-World (Stick)","type": "Mobilisation","region": "Schulter","desc": "1. Stab mit weitem Griff vor dem Körper\n2. gestreckte Arme über den Kopf nach hinten führen\n3. Rippen unten, kein Hohlkreuz","expl": "","dosage": "5–7x","src": "BER"},{"id": "cr173","name": "Shoulder Dislocates (Stick)","type": "Mobilisation","region": "Schulter","desc": "1. Stab/Band mit weitem Griff vor dem Körper\n2. Arme gestreckt über den Kopf hinter den Körper führen\n3. Griff nur so weit wie nötig, kontrolliert zurück","expl": "","dosage": "5–7x","src": "FT"},{"id": "cr174","name": "Shoulder External Rotation (Stick)","type": "Mobilisation","region": "Schulter","desc": "1. Ellbogen 90° am Körper, Stab in der Hand\n2. andere Hand drückt den Stab, Unterarm dreht nach außen\n3. Ellbogen bleibt am Körper","expl": "","dosage": "7–10x pro Seite","src": "BER"},{"id": "cr175","name": "Wrist Rocks (quadruped)","type": "Mobilisation","region": "Handgelenk/Ellbogen","desc": "1. Vierfüßlerstand\n2. Finger nach vorn / hinten / seitlich drehen\n3. Gewicht vor- und zurückverlagern","expl": "","dosage": "7-10x pro Richtung","src": "FT"},{"id": "cr176","name": "Wrist CARs","type": "Mobilisation","region": "Handgelenk/Ellbogen","desc": "1. Unterarm mit der anderen Hand fixieren\n2. Handgelenk in größtmöglichen langsamen Kreisen bewegen\n3. Richtung wechseln","expl": "","dosage": "5x pro Richtung","src": "FT"},{"id": "cr177","name": "Neck CARs (Controlled Rotations)","type": "Mobilisation","region": "Nacken","desc": "1. aufrecht sitzen\n2. Kopf langsam in größtmöglichen Kreisen bewegen\n3. nur im schmerzfreien Bereich, Richtung wechseln","expl": "","dosage": "3x pro Richtung","src": "FT"},{"id": "cr178","name": "World's Greatest Stretch","type": "Mobilisation","region": "Ganzkörper","desc": "1. Ausfallschritt, Hände innen neben dem vorderen Fuß\n2. Ellbogen zum Fuß, dann Arm zur Decke drehen\n3. vorderes Bein strecken (Hüfte nach hinten), Seite wechseln","expl": "","dosage": "5-7x pro Seite","src": "FMS"},{"id": "cr179","name": "Segmental Roll-Down (standing)","type": "Mobilisation","region": "Ganzkörper","desc": "1. Stand, Knie leicht gebeugt\n2. Kinn zur Brust, Wirbel für Wirbel nach unten abrollen\n3. ebenso Wirbel für Wirbel aufrichten","expl": "","dosage": "5–7x","src": "FT"},{"id": "cr180","name": "Deep Squat","type": "Mobilisation","region": "Ganzkörper","desc": "1. schulterbreiter Stand, tief in die Hocke\n2. Ellbogen drücken die Knie nach außen\n3. Fersen bleiben am Boden, Brust aufrecht","expl": "","dosage": "90-120x","src": "FMS"},{"id": "cr181","name": "Quadruped Thoracic Rotation (Thread the Needle)","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Vierfüßlerstand\n2. einen Arm unter dem Körper zur anderen Seite durchfädeln\n3. dann zur Decke aufdrehen, Blick folgt der Hand","expl": "","dosage": "6x pro Seite","src": "FT"},{"id": "cr182","name": "Standing Quad Stretch","type": "Dehnung","region": "Hüfte","desc": "1. Einbeinstand (bei Bedarf festhalten)\n2. Fuß zum Gesäß ziehen, Knie zusammen\n3. Gesäß anspannen, Rippen unten","expl": "","dosage": "30–45 Sek. pro Seite","src": "FT"},{"id": "cr183","name": "Standing Hamstring Stretch (Foot Elevated)","type": "Dehnung","region": "Hüfte","desc": "1. Ferse auf einer Erhöhung, Bein gestreckt\n2. Rücken flach, aus der Hüfte nach vorn neigen\n3. Fußspitze anziehen","expl": "","dosage": "30–45 Sek. pro Seite","src": "FT"},{"id": "cr184","name": "Wall Calf Stretch — Gastrocnemius","type": "Dehnung","region": "Fuß/Sprunggelenk","desc": "1. Hände an der Wand, Schrittstellung\n2. hinteres Bein gestreckt, Ferse am Boden\n3. Hüfte nach vorn schieben bis Zug in der Wade","expl": "","dosage": "30–45 Sek. pro Seite","src": "FT"},{"id": "cr185","name": "Wall Calf Stretch — Soleus","type": "Dehnung","region": "Fuß/Sprunggelenk","desc": "1. Hände an der Wand, Schrittstellung (kürzer)\n2. hinteres Knie beugen, Ferse bleibt am Boden\n3. Zug tief in der Wade/Achillessehne halten","expl": "","dosage": "30–45 Sek. pro Seite","src": "FT"},{"id": "cr186","name": "Doorway Pec Stretch","type": "Dehnung","region": "Schulter","desc": "1. Unterarm im Türrahmen auf Schulterhöhe\n2. mit dem gleichseitigen Bein durchtreten\n3. Brust öffnet sich, Schulter bleibt tief","expl": "","dosage": "30–45 Sek. pro Seite","src": "FT"},{"id": "cr187","name": "Cross-Body Shoulder Stretch","type": "Dehnung","region": "Schulter","desc": "1. Arm vor dem Körper zur Gegenseite\n2. mit der anderen Hand am Oberarm heranziehen\n3. Schulter tief halten","expl": "","dosage": "30 Sek. pro Seite","src": "FT"},{"id": "cr188","name": "Overhead Triceps Stretch","type": "Dehnung","region": "Schulter","desc": "1. Arm über Kopf, Ellbogen beugen\n2. mit der anderen Hand den Ellbogen hinter den Kopf ziehen\n3. Rippen unten","expl": "","dosage": "30 Sek. pro Seite","src": "FT"},{"id": "cr189","name": "Lat Stretch (Rack Reach)","type": "Dehnung","region": "Schulter","desc": "1. Hände an Stange/Bank auf Hüfthöhe\n2. Hüfte nach hinten schieben, Brust absenken\n3. zur Seite neigen für mehr Zug","expl": "","dosage": "30–45 Sek. pro Seite","src": "FT"},{"id": "cr190","name": "Standing Forward Fold","type": "Dehnung","region": "Ganzkörper","desc": "1. hüftbreiter Stand, Knie leicht gebeugt\n2. Oberkörper nach vorn hängen lassen\n3. Kopf und Arme locker, ruhig atmen","expl": "","dosage": "45–60 Sek.","src": "FT"},{"id": "cr191","name": "Cossack Adductor Hold","type": "Dehnung","region": "Hüfte","desc": "1. weiter Stand\n2. in eine Hüfte setzen, anderes Bein gestreckt (Fußspitze oben)\n3. Oberkörper aufrecht, Position halten","expl": "","dosage": "30–45 Sek. pro Seite","src": "FT"},{"id": "cr192","name": "Lateral Neck Stretch","type": "Dehnung","region": "Nacken","desc": "1. aufrecht sitzen, eine Hand unter das Gesäß\n2. Ohr Richtung Schulter neigen\n3. mit der anderen Hand leichten Zug geben","expl": "","dosage": "20–30 Sek. pro Seite","src": "FT"},{"id": "cr193","name": "Frog Stretch (Static Hold)","type": "Dehnung","region": "Hüfte","desc": "1. Frosch-Position: Knie weit, Unterschenkel parallel\n2. Hüfte nach hinten sinken lassen\n3. Position halten, ruhig atmen","expl": "","dosage": "60–90 Sek.","src": "FT"},{"id": "cr194","name": "Adductor Rock-Back (Hold)","type": "Dehnung","region": "Hüfte","desc": "1. Vierfüßlerstand, ein Bein seitlich gestreckt\n2. Hüfte nach hinten schieben\n3. Rücken flach, Position halten","expl": "","dosage": "45 Sek. pro Seite","src": "FT"},{"id": "cr195","name": "Neck Extensor Stretch (Chin Nod)","type": "Dehnung","region": "Nacken","desc": "1. aufrecht sitzen\n2. kleines Nicken (Doppelkinn)\n3. Hinterkopf nach oben lang machen","expl": "","dosage": "20–30 Sek.","src": "FMS"},{"id": "cr196","name": "Pigeon Pose (Eka Pada Rajakapotasana)","type": "Dehnung","region": "Hüfte","desc": "1. vorderes Bein angewinkelt vor dem Körper, hinteres Bein lang\n2. Hüfte gerade ausrichten\n3. Oberkörper langsam nach vorn ablegen","expl": "","dosage": "60–90 Sek. pro Seite","src": "BER"},{"id": "cr197","name": "Reclined Figure-4 (Supine Pigeon)","type": "Dehnung","region": "Hüfte","desc": "1. Rückenlage, Fuß auf das gegenüberliegende Knie legen\n2. hinteren Oberschenkel mit beiden Händen heranziehen\n3. Kopf und Schultern bleiben entspannt","expl": "","dosage": "60 Sek. pro Seite","src": "BER"},{"id": "cr198","name": "Cobra","type": "Dehnung","region": "Brustwirbelsäule","desc": "1. Bauchlage, Ellbogen unter den Schultern\n2. Oberkörper aufrichten, Gesäß locker\n3. Schultern weg von den Ohren","expl": "","dosage": "30–45 Sek.","src": "BER"},{"id": "cr199","name": "Low Lunge (Anjaneyasana)","type": "Dehnung","region": "Hüfte","desc": "1. tiefer Ausfallschritt, hinteres Knie am Boden\n2. Hüfte nach vorn-unten sinken lassen\n3. Arme über Kopf, Rippen unten","expl": "","dosage": "45–60 Sek. pro Seite","src": "BER"},{"id": "cr200","name": "Half Split (Ardha Hanumanasana)","type": "Dehnung","region": "Hüfte","desc": "1. Kniestand, vorderes Bein gestreckt (Fußspitze anziehen)\n2. Hüfte über das hintere Knie zurückschieben\n3. Rücken lang, aus der Hüfte nach vorn neigen","expl": "","dosage": "45–60 Sek. pro Seite","src": "BER"},{"id": "cr201","name": "Seated Forward Bend (Paschimottanasana)","type": "Dehnung","region": "Hüfte","desc": "1. Langsitz, Beine gestreckt\n2. Rücken lang, aus der Hüfte nach vorn neigen\n3. Hände an Schienbeine oder Füße","expl": "","dosage": "60–90 Sek.","src": "BER"},{"id": "cr202","name": "Bound Angle / Butterfly (Baddha Konasana)","type": "Dehnung","region": "Hüfte","desc": "1. Sitz, Fußsohlen zusammen\n2. Füße greifen, Rücken lang\n3. aus der Hüfte nach vorn falten","expl": "","dosage": "60–90 Sek.","src": "BER"},{"id": "cr203","name": "Supine Spinal Twist (Supta Matsyendrasana)","type": "Dehnung","region": "Brustwirbelsäule","desc": "1. Rückenlage, Arme seitlich ausgestreckt\n2. Knie gebeugt zu einer Seite ablegen\n3. Schultern bleiben am Boden, Blick zur Gegenseite","expl": "","dosage": "45–60 Sek. pro Seite","src": "BER"},{"id": "cr204","name": "Happy Baby (Ananda Balasana)","type": "Dehnung","region": "Hüfte","desc": "1. Rückenlage, Knie zur Brust\n2. Außenkanten der Füße greifen, Knie Richtung Achseln ziehen\n3. unterer Rücken bleibt am Boden","expl": "","dosage": "45–60 Sek.","src": "BER"},{"id": "cr205","name": "Thread the Needle (Yoga Hold)","type": "Dehnung","region": "Brustwirbelsäule","desc": "1. Vierfüßlerstand\n2. einen Arm unter dem Körper durchfädeln\n3. Schulter und Wange auf den Boden ablegen und halten","expl": "","dosage": "45 Sek. pro Seite","src": "BER"},{"id": "cr206","name": "Legs-Up-the-Wall (Viparita Karani)","type": "Dehnung","region": "Ganzkörper","desc": "1. Rückenlage, Gesäß nah an der Wand\n2. Beine gestreckt an der Wand ablegen\n3. Arme locker, ruhig atmen","expl": "","dosage": "2–3 Min.","src": "BER"},{"id": "cr207","name": "Half-Kneeling Adductor Rock-Back","type": "Dehnung","region": "Hüfte","desc": "1. Kniestand, ein Bein seitlich gestreckt\n2. Hände vor dem Körper\n3. Hüfte zurückschieben, Rücken flach","expl": "","dosage": "45 Sek. pro Seite","src": "FT"},{"id": "cr208","name": "Box Breathing (4-4-4-4)","type": "Atmung","region": "Atmung","desc": "1. aufrecht sitzen, Schultern locker\n2. 4 Sek. durch die Nase ein – 4 Sek. halten\n3. 4 Sek. aus – 4 Sek. halten\n4. Atmung in den Bauch, nicht in die Schultern","expl": "","dosage": "5–10 Runden","src": "BER"},{"id": "cr209","name": "4-7-8 Breathing","type": "Atmung","region": "Atmung","desc": "1. bequem sitzen oder liegen, Zunge hinter den oberen Schneidezähnen\n2. 4 Sek. durch die Nase einatmen\n3. 7 Sek. Luft anhalten\n4. 8 Sek. hörbar durch den Mund ausatmen","expl": "","dosage": "4–6 Runden","src": "BER"},{"id": "cr210","name": "Coherent Breathing (5-5)","type": "Atmung","region": "Atmung","desc": "1. sitzen oder liegen, Augen schließen\n2. 5 Sek. durch die Nase ein, 5 Sek. durch die Nase aus\n3. gleichmäßig ohne Pausen, ruhig in den Bauch atmen","expl": "","dosage": "3–5 Min.","src": "BER"},{"id": "cr211","name": "Extended Exhale (4-8, ratio 1:2)","type": "Dehnung","region": "Ganzkörper","desc": "1. Rückenlage oder Sitz\n2. 4 Sek. durch die Nase einatmen\n3. 8 Sek. langsam (Nase oder Lippenbremse) ausatmen\n4. ideal zum Runterfahren nach dem Training/vor dem Schlafen","expl": "","dosage": "8–10 Runden: 4 Sek. ein · 8 Sek. aus","src": "BER"},{"id": "cr212","name": "Diaphragmatic Breathing (Supine 90/90)","type": "Atmung","region": "Atmung","desc": "1. Rückenlage, Füße an der Wand oder Unterschenkel auf Box (Hüfte/Knie 90°)\n2. eine Hand auf den Bauch, eine auf die Brust\n3. durch die Nase breit in die unteren Rippen und den Bauch atmen\n4. lang ausatmen, Rippen sinken nach unten","expl": "","dosage": "2–3 Min.","src": "FMS"},{"id": "cr213","name": "Wim Hof Style Breathing","type": "Atmung","region": "Atmung","desc": "1. sitzen oder liegen (nie im Wasser oder beim Autofahren!)\n2. 30 tiefe, zügige Atemzüge (tief ein, locker aus)\n3. nach dem letzten Ausatmen Luft anhalten, bis Atemreiz kommt\n4. tief einatmen, 15 Sek. halten – aktivierend, nicht vor dem Schlafen","expl": "","dosage": "3 Runden","src": "BER"},{"id": "cr214","name": "Calf/Ankle Rock","type": "Mobilisation","region": "Fuß/Sprunggelenk","desc": "1. halber Kniestand oder Schrittstellung\n2. Knie rhythmisch über die Zehen nach vorn schieben\n3. Last über den großen Zeh, Ferse bleibt unten","expl": "","dosage": "10x pro Seite","src": "FT"},{"id": "cr215","name": "Supine Hip Flexion — Band-Assisted","type": "Mobilisation","region": "Hüfte","desc": "1. Rückenlage, Band um den Fuß, Bein senkrecht\n2. Bein mit Hilfe des Bandes Richtung Kopf führen\n3. anderes Bein bleibt lang am Boden","expl": "","dosage": "8x pro Seite","src": "BER"},{"id": "cr216","name": "Hip Extension — Band-Assisted (Standing)","type": "Mobilisation","region": "Hüfte","desc": "1. Band hinter dem Oberschenkel befestigt (Zug nach vorn)\n2. Gesäß anspannen, Hüfte nach vorn strecken\n3. Rippen unten, kein Hohlkreuz","expl": "","dosage": "8x pro Seite","src": "BER"},{"id": "cr217","name": "Frog Stretch (Rocking)","type": "Mobilisation","region": "Hüfte","desc": "1. Vierfüßlerstand, Knie weit auseinander, Füße außen\n2. Unterarme auf dem Boden\n3. Hüfte rhythmisch nach hinten wippen","expl": "","dosage": "8–10x","src": "FT"},{"id": "cr218","name": "Spiderman with Reach","type": "Mobilisation","region": "Hüfte","desc": "1. Liegestützposition, ein Fuß außen neben die Hand\n2. Ellbogen zum Innenfuß senken\n3. Arm zur Decke drehen, Blick folgt der Hand","expl": "","dosage": "6x pro Seite","src": "FT"},{"id": "cr219","name": "Child's Pose with Side Bend","type": "Mobilisation","region": "Brustwirbelsäule","desc": "1. Child's Pose, Arme lang nach vorn\n2. beide Hände zu einer Seite wandern lassen\n3. Zug in der Flanke halten, Seite wechseln","expl": "","dosage": "6x pro Seite","src": "BER"},{"id": "cr220","name": "Prone Y-T-W","type": "Mobilisation","region": "Schulter","desc": "1. Bauchlage, Stirn auf einem Handtuch\n2. Arme in Y-, T- und W-Position anheben\n3. Daumen oben, Schultern weg von den Ohren","expl": "","dosage": "je 6–8x","src": "FMS"},{"id": "cr221","name": "Band Pull-Apart","type": "Mobilisation","region": "Schulter","desc": "1. Band vor der Brust, Arme gestreckt\n2. Band auseinanderziehen, Schulterblätter zusammen\n3. kontrolliert zurück","expl": "","dosage": "12–15x","src": "FT"},{"id": "cr222","name": "Wall Slide with Lift-Off","type": "Mobilisation","region": "Schulter","desc": "1. Unterarme an der Wand\n2. nach oben schieben\n3. oben Unterarme kurz von der Wand lösen, zurück","expl": "","dosage": "8–10x","src": "FMS"},{"id": "cr223","name": "Deep Squat Prying","type": "Mobilisation","region": "Ganzkörper","desc": "1. tiefe Hocke, Hände vor der Brust\n2. Ellbogen drücken die Knie nach außen\n3. Becken sanft hin und her bewegen, 2 Sek. halten","expl": "","dosage": "6–8x","src": "FMS"},{"id": "cr224","name": "Downward-Facing Dog (Adho Mukha Svanasana)","type": "Dehnung","region": "Ganzkörper","desc": "1. Liegestützposition, Gesäß nach oben schieben\n2. Rücken lang, Arme gestreckt\n3. Fersen abwechselnd Richtung Boden senken","expl": "","dosage": "45–60 Sek.","src": "BER"},{"id": "cr225","name": "Cat-Cow (Slow, Breath-Led)","type": "Atmung","region": "Atmung","desc": "1. Vierfüßlerstand\n2. einatmen: Brust nach vorn, Becken kippen, Blick leicht nach vorn\n3. ausatmen: Rücken rund, Kinn zur Brust\n4. Bewegung folgt dem Atem, langsam","expl": "","dosage": "8–10 langsame Zyklen","src": "BER"},{"id": "cr226","name": "Physiological Sigh","type": "Atmung","region": "Atmung","desc": "1. aufrecht sitzen oder stehen\n2. tief durch die Nase einatmen, kurz nachatmen (zweiter kleiner Atemzug)\n3. lang und langsam durch den Mund ausatmen\n4. 3–5x wiederholen – schnelle Beruhigung","expl": "","dosage": "3–5 Wdh.","src": "BER"},{"id": "cr227","name": "Tactical / Combat Breathing (4-4-4)","type": "Atmung","region": "Atmung","desc": "1. aufrecht sitzen oder stehen\n2. 4 Sek. durch die Nase einatmen\n3. 4 Sek. halten\n4. 4 Sek. ausatmen – vor Wettkampf/Belastung zur Fokussierung","expl": "","dosage": "6–10 Runden","src": "BER"},{"id": "cr228","name": "Segmented / Stair Breathing","type": "Atmung","region": "Atmung","desc": "1. sitzen oder liegen\n2. in drei kurzen Zügen durch die Nase einatmen (Bauch – Flanken – Brust)\n3. langsam vollständig ausatmen","expl": "","dosage": "4–6 Runden","src": "BER"},{"id": "cr229","name": "90/90 Breathing with Balloon","type": "Atmung","region": "Atmung","desc": "1. Rückenlage, Füße an der Wand (Hüfte/Knie 90°), Ballon in einer Hand\n2. durch die Nase einatmen\n3. vollständig in den Ballon ausatmen, Rippen sinken\n4. Zunge an den Gaumen, Pause, erneut durch die Nase einatmen ohne Luft aus dem Ballon zu verlieren","expl": "","dosage": "5 Atemzüge","src": "FMS"},{"id": "cr230","name": "Nasal Cadence Breathing (Walk)","type": "Atmung","region": "Atmung","desc": "1. locker gehen\n2. 3 Schritte durch die Nase ein, 3 Schritte durch die Nase aus\n3. Mund geschlossen, Tempo so wählen, dass es ruhig bleibt","expl": "","dosage": "1–2 Min. gehen","src": "FT"}];
